def texts(lang: str) -> dict:
    """The texts of one language (Spanish for anything missing, never an empty label)."""
    return {**ES, **T.get(lang if lang in T else 'es', {})}


def pick_lang(fixed: str | None, query_lang: str | None, accept_language: str | None) -> str:
    """The centre's fixed language wins; otherwise ?lang= of the page; otherwise the visitor's browser; otherwise Spanish."""
    for cand in (fixed, query_lang):
        c = str(cand or '').lower()[:2]
        if c in LANGS: return c
    for part in str(accept_language or '').split(','):
        c = part.strip().lower()[:2]
        if c in LANGS: return c
    return 'es'
